 private void showLogin(){LinearLayout page=entrancePage();LinearLayout form=col();form.setPadding(0,dp(8),0,dp(16));String address=getPreferences(0).getString("server","https://cam.lex42.ru");CredentialsStore.Credential saved=credentials.load(address);EditText mail=field("Электронная почта",saved==null?"":saved.username,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),pass=field("Пароль","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);fieldAdd(form,mail);fieldAdd(form,pass);CheckBox remember=new CheckBox(this);remember.setText("Запомнить вход");remember.setTextColor(ink);remember.setChecked(saved!=null);form.addView(remember);TextView status=note("");Button enter=button("Войти",()->{});enter.setOnClickListener(v->startLogin(mail.getText().toString().trim(),pass.getText().toString(),remember.isChecked(),enter,status,false));enter.setBackground(shape(accent,10));enter.setTextColor(Color.rgb(10,35,39));fieldAdd(form,enter);form.addView(status);page.addView(form);}
 private void startLogin(String username,String password,boolean remember,Button login,TextView status,boolean automatic){
  if(username.isEmpty()||password.isEmpty()){status.setText("Введите почту и пароль");return;}
  final String address=getPreferences(0).getString("server","https://cam.lex42.ru");server=address;pendingUser=username;pendingPassword=password;pendingRemember=remember;if(!remember)credentials.clear();final int requestId=++generation;login.setEnabled(false);status.setText("Подключение…");
  io.execute(()->{try{JSONObject j=new JSONObject(request("POST",address+"/?json=true","mail="+enc(username)+"&pass="+enc(password)+"&function=dash&machineID="+enc(machineId())));JSONObject u=j.optJSONObject("$user");if(u==null)u=j;String a=u.optString("auth_token",u.optString("auth","")),g=u.optString("ke"),id=u.optString("uid");if(a.isEmpty()&&!g.isEmpty()&&!id.isEmpty()){ui(requestId,()->{login.setEnabled(true);promptFactor(g,id,requestId,login,status);});return;}if(a.isEmpty()||g.isEmpty()||id.isEmpty())throw new IOException("Не удалось войти. Проверьте почту и пароль.");if(requestId!=generation||destroyed)return;auth=a;group=g;uid=id;connectSocket(requestId);if(requestId!=generation)return;loadCameras(requestId);}catch(Exception e){if(requestId!=generation||destroyed)return;closeSocket();auth=null;pendingPassword="";ui(requestId,()->{if(automatic){showLogin();error(safeError(e));}else{login.setEnabled(true);status.setText(safeError(e));}});}});
 }
 private void installCrashLog(){Thread.UncaughtExceptionHandler previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((thread,error)->{try{StringBuilder b=new StringBuilder(error.getClass().getName());for(StackTraceElement frame:error.getStackTrace())b.append("\n").append(frame.toString());getPreferences(0).edit().putString("last_crash",b.toString()).commit();}catch(Throwable ignored){}if(previous!=null)previous.uncaughtException(thread,error);});}
    private String machineId(){String s=getPreferences(MODE_PRIVATE).getString("machine_id","");if(s.isEmpty()){s=UUID.randomUUID().toString();getPreferences(MODE_PRIVATE).edit().putString("machine_id",s).apply();}return s;}
    private void promptFactor(String ke,String userId,int requestId,Button loginButton,TextView status){
        EditText code=field("Код подтверждения","",InputType.TYPE_CLASS_NUMBER);
        new AlertDialog.Builder(this).setTitle("Подтверждение входа").setView(code).setNegativeButton("Отмена",(d,w)->showLogin()).setOnCancelListener(d->showLogin()).setPositiveButton("Войти",(dialog,which)->{
            String value=code.getText().toString().trim();loginButton.setEnabled(false);status.setText("Подтверждение входа…");io.execute(()->{try{String data="ke="+enc(ke)+"&id="+enc(userId)+"&machineID="+enc(machineId())+"&factorAuthKey="+enc(value)+"&function=dash";JSONObject j=new JSONObject(request("POST",server+"/?json=true",data));JSONObject u=j.optJSONObject("$user");if(u==null)u=j;String a=u.optString("auth_token","");if(a.isEmpty())throw new IOException("Не удалось подтвердить вход.");if(requestId!=generation)return;auth=a;group=u.optString("ke",ke);uid=u.optString("uid",userId);ui(requestId,()->status.setText("Подключение камер…"));connectSocket(requestId);loadCameras(requestId);}catch(Exception e){if(requestId!=generation)return;closeSocket();auth=null;group=null;uid=null;ui(requestId,()->{loginButton.setEnabled(true);status.setText("");error(safeError(e));});}});
        }).show();
    }
    private void connectSocket(int requestId) throws Exception {
        if(destroyed||requestId!=generation||auth==null)throw new IOException("Не удалось подключить просмотр камер.");
        closeSocket();CountDownLatch ready=new CountDownLatch(1);IO.Options options=IO.Options.builder().setPath("/socket.io").setTransports(new String[]{"websocket"}).build();Socket s=IO.socket(server,options);socket=s;
        s.on(Socket.EVENT_CONNECT,args->{if(socket!=s||destroyed)return;try{s.emit("f",new JSONObject().put("f","init").put("ke",group).put("uid",uid).put("auth",auth));}catch(JSONException ignored){}});
        s.on("f",args->{if(socket!=s||destroyed)return;if(args.length>0&&args[0] instanceof JSONObject&&"init_success".equals(((JSONObject)args[0]).optString("f"))){boolean again=ready.getCount()==0;socketReady=true;ready.countDown();if(again)runOnUiThread(()->{if(socket==s&&started&&restorePage!=null&&("camera".equals(pageName)||("home".equals(pageName)&&tab==0)))restorePage.run();});}});
        s.on(Socket.EVENT_DISCONNECT,args->{if(socket==s){socketReady=false;watched.clear();runOnUiThread(()->{if(started&&auth!=null)Toast.makeText(this,"Связь потеряна · переподключаемся",Toast.LENGTH_SHORT).show();});}});s.connect();
        if(!ready.await(12,TimeUnit.SECONDS)||destroyed||requestId!=generation){if(socket==s)closeSocket();throw new IOException("Не удалось подключить просмотр камер.");}
    }
    private void watch(String id) throws Exception {
        Socket s=socket;if(s==null||!socketReady||!s.connected())throw new IOException("Нет соединения просмотра");
        if(watched.add(id)){
            CountDownLatch acknowledged=new CountDownLatch(1);
            Emitter.Listener listener=args->{if(args.length>0&&args[0] instanceof JSONObject){JSONObject event=(JSONObject)args[0];if("monitor_watch_on".equals(event.optString("f"))&&id.equals(event.optString("id")))acknowledged.countDown();}};
            s.on("f",listener);
            try{s.emit("f",new JSONObject().put("f","monitor").put("ff","watch_on").put("id",id).put("ke",group).put("uid",uid));if(!acknowledged.await(8,TimeUnit.SECONDS)){watched.remove(id);throw new IOException("Сервер не подтвердил просмотр");}}
            finally{s.off("f",listener);}
        }
    }
    private void unwatchAll(){Socket s=socket;if(s!=null&&s.connected())for(String id:new ArrayList<>(watched)){try{s.emit("f",new JSONObject().put("f","monitor").put("ff","watch_off").put("id",id).put("ke",group).put("uid",uid));}catch(JSONException ignored){}}watched.clear();}
    private void closeSocket(){unwatchAll();Socket old=socket;socket=null;socketReady=false;if(old!=null){old.off();old.disconnect();old.close();}}
    private String request(String method,String url,String body) throws IOException {
        HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);
        try {if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded; charset=UTF-8");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}}
            int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("Сервер ответил: HTTP "+code);
            try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>8*1024*1024)throw new IOException("Ответ сервера слишком большой");out.write(b,0,n);}return out.toString("UTF-8");}
        } finally {c.disconnect();}
    }
    private static String enc(String s) throws UnsupportedEncodingException { return URLEncoder.encode(s,"UTF-8"); }
    private String api(String path) {return server+"/"+Uri.encode(auth)+"/"+path;}
    private static String safeError(Exception e) { return e instanceof IOException && e.getMessage()!=null && (e.getMessage().startsWith("Сервер ответил")||e.getMessage().startsWith("Не удалось")) ? e.getMessage() : "Не удалось связаться с Shinobi или обработать ответ."; }
    private void ui(int request,Runnable r){runOnUiThread(()->{if(request==generation&&!destroyed&&!isFinishing())r.run();});}
 private void loadCameras(int requestId)throws Exception{if(requestId!=generation)return;ApiClient apiClient=new ApiClient(server,auth,group,uid);List<ApiClient.Camera> found=apiClient.getCameras();if(requestId!=generation)return;boolean saveFailed=false;if(pendingRemember&&!pendingPassword.isEmpty())try{credentials.save(server,pendingUser,pendingPassword);}catch(Exception e){saveFailed=true;}pendingPassword="";boolean failed=saveFailed;ui(requestId,()->{client=apiClient;cameras.clear();cameras.addAll(found);restoreOrder();showHome(0);if(failed)error("Вход выполнен, но сохранить пароль не удалось.");});}
 private String orderKey(){return "camera_order_"+server+"_"+group+"_"+uid;}
 private void restoreOrder(){try{JSONArray a=new JSONArray(getPreferences(0).getString(orderKey(),"[]"));Map<String,Integer> order=new HashMap<>();for(int i=0;i<a.length();i++)order.put(a.getString(i),i);Collections.sort(cameras,(x,y)->Integer.compare(order.getOrDefault(x.id,Integer.MAX_VALUE),order.getOrDefault(y.id,Integer.MAX_VALUE)));}catch(Exception ignored){}}
 private void saveOrder(){JSONArray order=new JSONArray();for(ApiClient.Camera c:cameras)order.put(c.id);getPreferences(0).edit().putString(orderKey(),order.toString()).apply();}
 private View toolbarIcon(boolean back,String description,Runnable action){View icon=new View(this){final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);@Override protected void onDraw(Canvas canvas){float size=dp(22),x=(getWidth()-size)/2,y=(getHeight()-size)/2;canvas.save();canvas.translate(x,y);canvas.scale(size/24,size/24);pen.setColor(ink);pen.setStyle(Paint.Style.STROKE);pen.setStrokeWidth(1.8f);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);if(back){canvas.drawLine(14,5,7,12,pen);canvas.drawLine(7,12,14,19,pen);}else{canvas.drawCircle(12,12,7,pen);canvas.drawCircle(12,12,2.5f,pen);for(int n=0;n<8;n++){double angle=n*Math.PI/4;canvas.drawLine(12+(float)Math.cos(angle)*7,12+(float)Math.sin(angle)*7,12+(float)Math.cos(angle)*10,12+(float)Math.sin(angle)*10,pen);}}canvas.restore();}};icon.setContentDescription(description);icon.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(dark?0x22FFFFFF:0x18000000),null,shape(Color.WHITE,8)));icon.setClickable(true);icon.setFocusable(true);icon.setOnClickListener(v->action.run());return icon;}
 private android.graphics.drawable.Drawable mediaActionIcon(boolean share){android.graphics.drawable.Drawable icon=new android.graphics.drawable.Drawable(){final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);int color=ink;@Override public void draw(Canvas canvas){Rect r=getBounds();canvas.save();canvas.translate(r.left,r.top);canvas.scale(r.width()/24f,r.height()/24f);pen.setColor(color);pen.setStrokeWidth(1.8f);pen.setStyle(Paint.Style.STROKE);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);if(share){canvas.drawLine(7,11,16,6,pen);canvas.drawLine(7,13,16,18,pen);canvas.drawCircle(5,12,2.5f,pen);canvas.drawCircle(18,5,2.5f,pen);canvas.drawCircle(18,19,2.5f,pen);}else{canvas.drawLine(12,3,12,15,pen);canvas.drawLine(7,10,12,15,pen);canvas.drawLine(12,15,17,10,pen);canvas.drawLine(4,16,4,21,pen);canvas.drawLine(4,21,20,21,pen);canvas.drawLine(20,21,20,16,pen);}canvas.restore();}@Override public void setAlpha(int alpha){pen.setAlpha(alpha);}@Override public void setColorFilter(ColorFilter filter){pen.setColorFilter(filter);}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}@Override public int getIntrinsicWidth(){return dp(18);}@Override public int getIntrinsicHeight(){return dp(18);}@Override public void setTint(int tint){color=tint;invalidateSelf();}};return icon;}
