  void load(){TextView loading=note("Загружаем записи…");list.addView(loading);int screenId=requestId;io.execute(()->{try{long end=0;if(day>0){Calendar next=Calendar.getInstance();next.setTimeInMillis(day);next.add(Calendar.DAY_OF_MONTH,1);end=next.getTimeInMillis();}List<ApiClient.Recording> result=client.recordings(camera.id,day,end);ui(screenId,()->{records=new ArrayList<>(result);if(selected!=null){boolean found=false;for(ApiClient.Recording r:records)if(r.url.equals(selected.url))found=true;if(!found)records.add(0,selected);}renderList();});}catch(Exception e){ui(screenId,()->{loading.setText("Не удалось загрузить записи · повторить");loading.setOnClickListener(v->{list.removeAllViews();load();});});}});}
  void renderList(){list.removeAllViews();if(records.isEmpty()){list.addView(note("За это время записей нет"));return;}for(ApiClient.Recording record:records){boolean active=selected!=null&&record.url.equals(selected.url);LinearLayout item=row();item.setPadding(dp(12),dp(9),dp(8),dp(9));GradientDrawable background=shape(active?(dark?0xFF223E3C:0xFFE0F1ED):card,8);if(active)background.setStroke(dp(1),accent);item.setBackground(background);item.setTag(record.url);TextView marker=text(active?"▶":"▷",19);marker.setTextColor(active?accent:muted);item.addView(marker,new LinearLayout.LayoutParams(dp(29),-2));LinearLayout labels=col();TextView time=text(dateLabel(record.startMs),15);time.setTypeface(Typeface.create(active?"sans-serif-medium":"sans-serif",0));labels.addView(time);labels.addView(note(Math.max(1,(record.endMs-record.startMs)/1000)+" сек"));item.addView(labels,new LinearLayout.LayoutParams(0,-2,1));Button more=button("⋮",()->exportMenu(record));more.setContentDescription("Действия с записью "+dateLabel(record.startMs));more.setBackgroundColor(Color.TRANSPARENT);item.addView(more,new LinearLayout.LayoutParams(dp(40),dp(40)));item.setContentDescription("Запись "+dateLabel(record.startMs));item.setOnClickListener(v->{desiredPlaying=true;play(record,0);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(5));list.addView(item,lp);}files.post(()->{if(requestId==generation)files.scrollTo(0,scrollY);});}
  void play(ApiClient.Recording record,long offset){preparedPlayer=null;rateButton.setEnabled(false);status.setOnClickListener(null);seek.setTag(Boolean.FALSE);scrollY=files.getScrollY();selected=record;position=offset;stoppedRecordingPosition=offset;final int playback=++serial;releasePlayers();stage.removeAllViews();video=new VideoView(MainActivity.this);final VideoView current=video;recordingVideo=current;stage.addView(current,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));stage.addView(new ZoomGestureOverlay(MainActivity.this,current,this::toggleFull,null),new FrameLayout.LayoutParams(-1,-1));Button expand=button("⛶",this::toggleFull);expand.setContentDescription("На весь экран");expand.setTextColor(Color.WHITE);expand.setBackground(shape(0x77000000,7));FrameLayout.LayoutParams expandLp=new FrameLayout.LayoutParams(dp(42),dp(38),Gravity.TOP|Gravity.RIGHT);expandLp.setMargins(0,dp(4),dp(4),0);stage.addView(expand,expandLp);fullHeader=row();fullHeader.setPadding(dp(8),dp(4),dp(8),dp(4));fullHeader.setBackgroundColor(0x66000000);Button close=button("‹",this::toggleFull);close.setTextColor(Color.WHITE);close.setBackgroundColor(Color.TRANSPARENT);close.setContentDescription("Выйти из полного экрана");fullHeader.addView(close,new LinearLayout.LayoutParams(dp(44),dp(40)));TextView fullName=text(camera.name,17);fullName.setTextColor(Color.WHITE);fullHeader.addView(fullName);stage.addView(fullHeader,new FrameLayout.LayoutParams(-1,dp(48),Gravity.TOP));fullHeader.setVisibility(full?View.VISIBLE:View.GONE);if(full){if(controls.getParent()!=null)((ViewGroup)controls.getParent()).removeView(controls);stage.addView(controls,new FrameLayout.LayoutParams(-1,dp(88),Gravity.BOTTOM));}stage.setOnApplyWindowInsetsListener((v,insets)->{int left=0,right=0,top=0,bottom=0;if(full){left=insets.getSystemWindowInsetLeft();right=insets.getSystemWindowInsetRight();top=insets.getSystemWindowInsetTop();bottom=insets.getSystemWindowInsetBottom();if(Build.VERSION.SDK_INT>=28&&insets.getDisplayCutout()!=null){left=Math.max(left,insets.getDisplayCutout().getSafeInsetLeft());right=Math.max(right,insets.getDisplayCutout().getSafeInsetRight());top=Math.max(top,insets.getDisplayCutout().getSafeInsetTop());}}fullHeader.setPadding(left+dp(8),top,right+dp(8),0);controls.setPadding(left,0,right,bottom);return insets;});playerArea.setVisibility(View.VISIBLE);if(archiveHint==null&&!getPreferences(0).getBoolean("hint_recording",false)){archiveHint=gestureHint("hint_recording","Двойное касание видео или ⛶ — полный экран. Два пальца — увеличение.");playerArea.addView(archiveHint);if(full)archiveHint.setVisibility(View.GONE);}quality.setText(high?"4К":"SD");pause.setText(desiredPlaying?"Ⅱ":"▶");status.setText("Загрузка · "+(high?"4К":"SD"));seek.setMax((int)Math.min(Integer.MAX_VALUE,Math.max(1,record.endMs-record.startMs)));seek.setProgress((int)offset);if(records!=null)renderList();final boolean requestedHigh=high;current.setOnPreparedListener(mp->{if(!valid(playback))return;mp.setVolume(0,0);preparedPlayer=mp;rateButton.setEnabled(true);applyRate(rate);if(offset>0)current.seekTo((int)Math.min(Integer.MAX_VALUE,offset));if(started&&desiredPlaying)current.start();status.setText(dateLabel(record.startMs)+" · "+(requestedHigh?"4К":"SD"));});current.setOnInfoListener((mp,what,extra)->{if(!valid(playback))return false;if(what==android.media.MediaPlayer.MEDIA_INFO_BUFFERING_START)status.setText("Буферизация…");else if(what==android.media.MediaPlayer.MEDIA_INFO_BUFFERING_END)status.setText(dateLabel(record.startMs)+" · "+(requestedHigh?"4К":"SD"));return false;});current.setOnErrorListener((mp,what,extra)->{if(valid(playback)){status.setText("Ошибка видео · повторить");status.setOnClickListener(v->play(record,offset));}return true;});current.setOnCompletionListener(mp->{if(valid(playback)){desiredPlaying=false;status.setText("Запись закончилась");pause.setText("▶");}});ApiClient session=client;io.execute(()->{try{String url=requestedHigh?record.url:session.variants(record).lowUrl;ui(requestId,()->{if(!valid(playback))return;if(url==null||url.isEmpty()){status.setText("SD недоступно · выберите 4К");return;}current.setVideoURI(Uri.parse(url));});}catch(Exception e){ui(requestId,()->{if(valid(playback)){status.setText("Нет связи · повторить");status.setOnClickListener(v->play(record,offset));}});}});handler.post(new Runnable(){public void run(){if(!valid(playback))return;int pos=Math.max(0,current.getCurrentPosition());position=pos;if(!Boolean.TRUE.equals(seek.getTag()))seek.setProgress(pos);elapsed.setText(String.format(Locale.ROOT,"%02d:%02d / %02d:%02d",pos/60000,pos/1000%60,seek.getMax()/60000,seek.getMax()/1000%60));handler.postDelayed(this,500);}});
  }
